function validate([operations, args]) {
  if (!Array.isArray(operations) || operations.length !== 1 || operations[0] !== 'NestedIterator') return 'Each case is [["NestedIterator"], [[nestedList]]]; the judge calls hasNext and next itself.';
  if (!Array.isArray(args) || args.length !== 1 || !Array.isArray(args[0]) || args[0].length !== 1 || !Array.isArray(args[0][0])) return 'Pass nestedList as the only constructor argument.';
  const nestedList = args[0][0];
  if (nestedList.length < 1 || nestedList.length > 500) return 'nestedList needs 1 to 500 items.';
  const check = (list, depth) => {
    for (const item of list) {
      if (Array.isArray(item)) {
        if (depth >= 8) return 'Lists nest at most 8 levels deep inside nestedList.';
        const problem = check(item, depth + 1);
        if (problem) return problem;
      } else if (!Number.isInteger(item) || item < -1000000 || item > 1000000) {
        return 'Every item is a list or a whole number from -10^6 to 10^6.';
      }
    }
    return null;
  };
  return check(nestedList, 0);
}

