function adapt(input, solve, kit) {
  // LeetCode provides NestedInteger; this is the same read-only API.
  class NestedInteger {
    constructor(value) {
      this._value = value;
    }
    isInteger() { return !Array.isArray(this._value); }
    getInteger() { return Array.isArray(this._value) ? null : this._value; }
    getList() { return Array.isArray(this._value) ? this._value : null; }
  }
  globalThis.NestedInteger = NestedInteger;
  const wrap = item => new NestedInteger(Array.isArray(item) ? item.map(wrap) : item);
  const raw = input[1][0][0];
  let total = 0;
  const count = item => { if (Array.isArray(item)) item.forEach(count); else total++; };
  count(raw);
  // The judge's loop from the statement: hasNext(), then next(), until hasNext() is false.
  const iterator = new solve(raw.map(wrap));
  const result = [];
  while (iterator.hasNext()) {
    if (result.length === total) throw new Error('hasNext() still returns true after every integer was returned.');
    const value = iterator.next();
    result.push(value === undefined ? null : value);
  }
  return result;
}

