class NestedIterator {
  constructor(nestedList) {
    this.lists = [nestedList];
    this.positions = [0];
  }

  hasNext() {
    while (this.lists.length > 0) {
      const depth = this.lists.length - 1;
      const list = this.lists[depth];
      const position = this.positions[depth];
      if (position === list.length) {
        this.lists.pop();
        this.positions.pop();
      } else if (list[position].isInteger()) {
        return true;
      } else {
        this.positions[depth]++;
        this.lists.push(list[position].getList());
        this.positions.push(0);
      }
    }
    return false;
  }

  next() {
    this.hasNext();
    const depth = this.lists.length - 1;
    const item = this.lists[depth][this.positions[depth]];
    this.positions[depth]++;
    return item.getInteger();
  }
}

