class NestedIterator {
  // Flatten everything up front with recursion, then read from an array.
  constructor(nestedList) {
    this.values = [];
    const visit = list => {
      for (const item of list) {
        if (item.isInteger()) this.values.push(item.getInteger());
        else visit(item.getList());
      }
    };
    visit(nestedList);
    this.index = 0;
  }
  next() { return this.values[this.index++]; }
  hasNext() { return this.index < this.values.length; }
}

