function generate(rand, size) {
  const large = size === 'large';
  const maxDepth = large ? 8 : 3;
  let budget = large ? 6000 : 20;
  const value = () => (large || rand() < 0.5 ? Math.floor(rand() * 2000001) - 1000000 : Math.floor(rand() * 7) - 3);
  const build = depth => {
    const list = [];
    const length = Math.floor(rand() * (large ? 6 : 4));
    for (let i = 0; i < length && budget > 0; i++) {
      budget--;
      list.push(depth < maxDepth && rand() < 0.35 ? build(depth + 1) : value());
    }
    return list;
  };
  const n = large ? 500 : 1 + Math.floor(rand() * 5);
  const nestedList = [];
  for (let i = 0; i < n; i++) nestedList.push(rand() < 0.45 ? build(1) : value());
  return [['NestedIterator'], [[nestedList]]];
}
